import {initializeApp} from 'https://www.gstatic.com/firebasejs/13.1.0/firebase-app.js';
import {getAuth,onAuthStateChanged,signInWithEmailAndPassword,signOut} from 'https://www.gstatic.com/firebasejs/13.1.0/firebase-auth.js';
import {getFirestore,doc,getDoc,getDocs,collection,addDoc,setDoc,updateDoc,deleteDoc,onSnapshot,serverTimestamp,writeBatch,Timestamp} from 'https://www.gstatic.com/firebasejs/13.1.0/firebase-firestore.js';
import {firebaseConfig} from './firebase-config.js';
import {initOptionalAppCheck} from './app-check-optional.js';
import {defaultContent,defaultServices,requestStatuses,appointmentStatuses,quoteStatuses,roleLabels,styledHeadingConfig,getStyledHeadingParts,renderStyledHeading} from './defaults.js';

const app=initializeApp(firebaseConfig);
await initOptionalAppCheck(app,firebaseConfig.appCheckSiteKey);
const auth=getAuth(app),db=getFirestore(app);
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const state={view:'dashboard',user:null,profile:null,collections:{requests:[],clients:[],appointments:[],quotes:[],services:[],projects:[],admins:[]},content:{...defaultContent},filters:{requests:'',clients:'',appointments:'',quotes:''},requestStatus:'',calendarMonth:new Date().getMonth(),calendarYear:new Date().getFullYear()};
let subscriptions=[];let knownRequestIds=null;
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const stamp=x=>x?.toDate?.()?.getTime?.()||new Date(x||0).getTime()||0;
const date=x=>x?new Date(stamp(x)).toLocaleDateString('it-IT',{day:'2-digit',month:'short',year:'numeric'}):'—';
const currency=n=>new Intl.NumberFormat('it-IT',{style:'currency',currency:'EUR'}).format(Number(n)||0);
const pretty=s=>String(s??'').replaceAll('_',' ');
const canStaff=()=>['owner','staff'].includes(state.profile?.role);
const canContent=()=>['owner','editor'].includes(state.profile?.role);
const canOperationsRead=()=>['owner','staff','viewer'].includes(state.profile?.role);
const canOwner=()=>state.profile?.role==='owner';
const all=key=>state.collections[key]||[];
const item=(key,id)=>all(key).find(x=>x.id===id);
const status=s=>`<span class="badge ${esc(s)}">${esc(pretty(s))}</span>`;
const textInput=(name,label,value='',type='text',extra='')=>`<label>${label}<input name="${esc(name)}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const textarea=(name,label,value='',rows=4)=>`<label class="full">${label}<textarea name="${esc(name)}" rows="${rows}">${esc(value)}</textarea></label>`;
const select=(name,label,values,current='')=>`<label>${label}<select name="${name}">${values.map(v=>{const [val,label]=Array.isArray(v)?v:[v,pretty(v)];return `<option value="${esc(val)}" ${val===current?'selected':''}>${esc(label)}</option>`}).join('')}</select></label>`;
const formatTime=t=>t||'—';
function toast(message,error=false){const el=document.createElement('div');el.className='toast'+(error?' error':'');el.textContent=message;$('#toast-stack').append(el);setTimeout(()=>el.remove(),4300)}
function fail(error){console.error(error);toast(error?.code==='permission-denied'?'Permesso negato: verifica ruolo e regole Firestore.':(error?.message||'Operazione non riuscita.'),true)}
function requireRole(kind){if(kind==='staff'&&!canStaff()||kind==='content'&&!canContent()||kind==='owner'&&!canOwner()){toast('Il tuo ruolo non consente questa operazione.',true);return false}return true}
function openModal(title,html){$('#modal-heading').textContent=title;$('#modal-content').innerHTML=html;
 const form=$('#modal-content form[data-save]');if(form){const type=form.dataset.save;
  const editable=(['request','client','appointment','quote'].includes(type)&&canStaff())||(['service','project'].includes(type)&&canContent())||(type==='member'&&canOwner());
  if(!editable){form.querySelectorAll('input,textarea,select').forEach(el=>el.disabled=true);form.querySelectorAll('[type="submit"],[data-delete],[data-add-line],[data-remove-line]').forEach(el=>el.hidden=true)}
 }
 $('#modal-backdrop').hidden=false;document.body.style.overflow='hidden';$('#modal-content input:not([type=hidden]):not(:disabled),#modal-content textarea:not(:disabled),#modal-content select:not(:disabled)')?.focus()}
function closeModal(){$('#modal-backdrop').hidden=true;$('#modal-content').innerHTML='';document.body.style.overflow=''}
$('#modal-close').addEventListener('click',closeModal);$('#modal-backdrop').addEventListener('click',e=>{if(e.target===e.currentTarget)closeModal()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
$('#today-string').textContent=new Date().toLocaleDateString('it-IT',{weekday:'short',day:'2-digit',month:'long'}).toUpperCase();
$('#login-form').addEventListener('submit',async e=>{e.preventDefault();$('#login-error').textContent='';const fd=new FormData(e.currentTarget),btn=$('#login-button');btn.disabled=true;btn.textContent='Verifica credenziali…';try{await signInWithEmailAndPassword(auth,String(fd.get('email')),String(fd.get('password')))}catch(error){$('#login-error').textContent='Accesso non riuscito. Controlla email, password e autorizzazioni Firebase.';console.error(error)}finally{btn.disabled=false;btn.innerHTML='Accedi al CMS <span>↗</span>'}});
$('#logout-btn').addEventListener('click',()=>signOut(auth));
$('#sidebar-toggle').addEventListener('click',()=>$('#sidebar').classList.toggle('open'));
$('#admin-nav').addEventListener('click',e=>{const btn=e.target.closest('[data-view]');if(!btn)return;show(btn.dataset.view);$('#sidebar').classList.remove('open')});

onAuthStateChanged(auth,async user=>{
 subscriptions.forEach(u=>u());subscriptions=[];
 if(!user){state.user=null;state.profile=null;$('#auth-screen').hidden=false;$('#app-shell').hidden=true;return}
 try{const snap=await getDoc(doc(db,'admins',user.uid));const profile=snap.data();if(!snap.exists()||profile.active!==true||!roleLabels[profile.role]){await signOut(auth);$('#login-error').textContent='Account autenticato ma non abilitato nel CMS. Crea admins/'+user.uid+' con active:true e role:"owner" dalla console Firebase.';return}
  state.user=user;state.profile=profile;$('#auth-screen').hidden=true;$('#app-shell').hidden=false;$('#user-email').textContent=user.email;$('#user-role').textContent=roleLabels[profile.role];$('#avatar').textContent=(user.email||'SR').slice(0,2).toUpperCase();
  $$('#admin-nav [data-view]').forEach(b=>{if(['requests','clients','appointments','quotes'].includes(b.dataset.view))b.style.display=canOperationsRead()?'':'none'});
  await loadAll();if(canOperationsRead())subscribe();show('dashboard');
 }catch(e){fail(e);await signOut(auth)}});

async function loadAll(){knownRequestIds=null;const keys=canOperationsRead()?['requests','clients','appointments','quotes','services','projects']:['services','projects'];const results=await Promise.allSettled(keys.map(k=>getDocs(collection(db,k))));results.forEach((res,i)=>{if(res.status==='fulfilled')state.collections[keys[i]]=res.value.docs.map(d=>({id:d.id,...d.data()}));else console.warn(keys[i],res.reason)});
 try{const c=await getDoc(doc(db,'siteContent','main'));state.content=c.exists()?{...defaultContent,...c.data()}:{...defaultContent}}catch(e){console.warn('Contenuti',e)}
 knownRequestIds=new Set(all('requests').map(r=>r.id));
 if(canOwner()){try{const s=await getDocs(collection(db,'admins'));state.collections.admins=s.docs.map(d=>({id:d.id,...d.data()}))}catch(e){console.warn('Ruoli',e)}}
}
function subscribe(){for(const key of ['requests','appointments']){try{const un=onSnapshot(collection(db,key),snap=>{const latest=snap.docs.map(d=>({id:d.id,...d.data()}));if(key==='requests'&&knownRequestIds){const arrived=latest.filter(r=>!knownRequestIds.has(r.id)&&r.status==='nuova');for(const r of arrived){toast('Nuova richiesta: '+String(r.fullName||'contatto').slice(0,80));if('Notification' in window&&Notification.permission==='granted')new Notification('Studio Russu — Nuova richiesta',{body:String(r.service||'Richiesta ricevuta').slice(0,100)})}knownRequestIds=new Set(latest.map(r=>r.id))}state.collections[key]=latest;updateRequestBadge();if(['dashboard',key,'export'].includes(state.view))render()},err=>console.warn(err));subscriptions.push(un)}catch(e){console.warn(e)}}}
function updateRequestBadge(){const n=all('requests').filter(r=>r.status==='nuova').length;$('#request-badge').hidden=!n;$('#request-badge').textContent=n}
async function refresh(key){try{const s=await getDocs(collection(db,key));state.collections[key]=s.docs.map(d=>({id:d.id,...d.data()}));updateRequestBadge();render()}catch(e){fail(e)}}
function heading(title,description,actions=''){return `<div class="page-heading"><div><span class="caps muted">STUDIO TECNICO RUSSU / WORKSPACE</span><h1>${title}</h1><p>${description}</p></div><div class="heading-actions">${actions}</div></div>`}
function card(label,value,foot='',symbol='↗',warm=false){return `<div class="stat ${warm?'warm':''}"><span class="stat-label">${esc(label)}</span><span class="stat-symbol">${symbol}</span><strong class="stat-value">${esc(value)}</strong><span class="stat-foot">${esc(foot)}</span></div>`}
function empty(title='Nessun elemento presente',extra=''){return `<div class="empty"><b>${esc(title)}</b>${esc(extra)}</div>`}
function show(view){if(['requests','clients','appointments','quotes'].includes(view)&&!canOperationsRead())view='dashboard';state.view=view;$$('#admin-nav [data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#crumb-name').textContent=({'dashboard':'PANORAMICA','requests':'RICHIESTE','clients':'CLIENTI','appointments':'APPUNTAMENTI','quotes':'PREVENTIVI','content':'CONTENUTI','services':'SERVIZI','projects':'PROGETTI','seo':'SEO','team':'COLLABORATORI','settings':'IMPOSTAZIONI','export':'ESPORTA'}[view]||view);render()}
function render(){const main=$('#admin-main');if(!state.user)return;main.innerHTML=({dashboard:renderDashboard,requests:renderRequests,clients:renderClients,appointments:renderAppointments,quotes:renderQuotes,content:renderContent,services:renderServices,projects:renderProjects,seo:renderSEO,team:renderTeam,settings:renderSettings,export:renderExport}[state.view]||renderDashboard)();if(state.view==='content')refreshHeadingPreviews(main);}

function renderDashboard(){if(!canOperationsRead())return heading('Panoramica.','Contenuti e strumenti disponibili per il tuo ruolo.')+`<div class="stats-grid">${card('Servizi gestiti',all('services').filter(s=>s.archived!==true).length,'Collezione Firestore','▤')}${card('Progetti in archivio',all('projects').length,'Portfolio pubblico disattivato','◇')}</div>`;const req=all('requests'),pend=req.filter(x=>x.status==='nuova').length,progress=req.filter(x=>x.status==='in_lavorazione').length,ap=all('appointments').filter(x=>x.status==='da_confermare').length;return heading('Panoramica.','Una vista chiara su richieste, attività e scadenze.',`<a href="../index.html" target="_blank" class="outline-btn">Apri il sito ↗</a>`)+`<div class="stats-grid">${card('Richieste totali',req.length,'Dal modulo del sito','▤',true)}${card('Nuove richieste',pend,'Da prendere in carico','◉')}${card('In lavorazione',progress,'Attività in corso','↗')}${card('Appuntamenti da confermare',ap,'Calendario studio','▦')}</div><div class="dashboard-grid"><div class="panel"><div class="panel-top"><div><h2>Ultime richieste</h2><p>In arrivo direttamente dal form pubblico</p></div><button class="outline-btn btn-small" data-goto="requests">Vedi tutte →</button></div><div class="panel-body table-scroll">${requestTable(req.sort((a,b)=>stamp(b.createdAt)-stamp(a.createdAt)).slice(0,6),true)}</div></div><div class="panel"><div class="panel-top"><div><h2>Stati delle richieste</h2><p>Statistiche operative, non traffico web</p></div></div><div class="panel-body">${req.length?`<div class="bar-chart">${requestStatuses.map(s=>{const n=req.filter(x=>x.status===s).length;return `<div class="bar-col"><b>${n}</b><i style="height:${Math.max(6,100*n/Math.max(1,req.length))}px"></i><span>${esc(pretty(s))}</span></div>`}).join('')}</div>`:empty('Nessun dato da mostrare','Le statistiche compariranno quando arriveranno richieste.')}</div></div></div><div class="two-cols"><div class="panel"><div class="panel-top"><div><h2>Accesso rapido</h2><p>Azioni operative</p></div></div><div class="panel-body"><div class="heading-actions"><button class="outline-btn" data-goto="clients">Gestisci clienti ↗</button><button class="outline-btn" data-goto="appointments">Calendario ↗</button><button class="outline-btn" data-goto="quotes">Preventivi ↗</button></div></div></div><div class="panel"><div class="panel-top"><h2>Workspace attivo</h2></div><div class="panel-body"><p>Account: <b>${esc(state.user.email)}</b><br>Permessi: <b>${esc(roleLabels[state.profile.role])}</b><br>Database: <b>studio-russu / Firestore</b></p></div></div></div>`}
function requestTable(data,compact=false){return data.length?`<table class="list-table"><thead><tr><th>CONTATTO</th><th>SERVIZIO</th><th>DATA</th><th>STATO</th><th></th></tr></thead><tbody>${data.map(r=>`<tr><td><span class="strong">${esc(r.fullName)}</span><br><span class="text-muted">${esc(r.email)}</span></td><td>${esc(r.service)}</td><td>${date(r.createdAt)}</td><td>${status(r.status)}</td><td><button class="action-icon" data-open="request" data-id="${esc(r.id)}" aria-label="Apri richiesta">↗</button></td></tr>`).join('')}</tbody></table>`:empty('Nessuna richiesta','Gli invii del modulo pubblico compariranno qui.')}
function renderRequests(){const data=all('requests').filter(r=>(!state.filters.requests||[r.fullName,r.email,r.service,r.message].some(v=>String(v||'').toLowerCase().includes(state.filters.requests.toLowerCase())))&&(!state.requestStatus||r.status===state.requestStatus)).sort((a,b)=>stamp(b.createdAt)-stamp(a.createdAt));return heading('Richieste.','Dalla prima domanda fino alla presa in carico.')+`<div class="filters"><input id="filter-requests" placeholder="Cerca per nome, email o servizio" value="${esc(state.filters.requests)}"><select id="status-requests"><option value="">Tutti gli stati</option>${requestStatuses.map(s=>`<option value="${s}" ${state.requestStatus===s?'selected':''}>${pretty(s)}</option>`).join('')}</select><button class="outline-btn" data-refresh="requests">Aggiorna ↻</button></div><div class="panel"><div class="panel-top"><h2>${data.length} richieste</h2><span class="text-muted">Le richieste non sono visibili al pubblico</span></div><div class="panel-body table-scroll">${requestTable(data)}</div></div>`}
function renderClients(){const q=state.filters.clients.toLowerCase();const data=all('clients').filter(c=>!q||[c.name,c.email,c.phone,c.company].some(x=>String(x||'').toLowerCase().includes(q))).sort((a,b)=>String(a.name||'').localeCompare(String(b.name||'')));return heading('Anagrafica clienti.','Contatti, riferimenti e note organizzati in un unico archivio.',canStaff()?'<button class="primary-btn" data-new="client">+ Nuovo cliente</button>':'')+`<div class="filters"><input id="filter-clients" placeholder="Cerca tra i clienti" value="${esc(state.filters.clients)}"><button class="outline-btn" data-refresh="clients">Aggiorna ↻</button></div><div class="panel"><div class="panel-body table-scroll">${data.length?`<table class="list-table"><thead><tr><th>NOMINATIVO</th><th>CONTATTI</th><th>NOTE</th><th></th></tr></thead><tbody>${data.map(c=>`<tr><td><b>${esc(c.name)}</b><br><span class="text-muted">${esc(c.company||'Privato')}</span></td><td>${esc(c.email||'—')}<br>${esc(c.phone||'')}</td><td>${esc((c.notes||'').slice(0,70))}</td><td><button class="action-icon" data-open="client" data-id="${esc(c.id)}">↗</button></td></tr>`).join('')}</tbody></table>`:empty('Nessun cliente','Aggiungi clienti dal CMS o converti una richiesta.')}</div></div>`}
function renderAppointments(){const data=all('appointments').filter(a=>!state.filters.appointments||[a.name,a.service,a.date].some(x=>String(x||'').toLowerCase().includes(state.filters.appointments.toLowerCase()))).sort((a,b)=>String(a.date).localeCompare(String(b.date)));const now=new Date(),y=state.calendarYear,m=state.calendarMonth,first=(new Date(y,m,1).getDay()+6)%7,days=new Date(y,m+1,0).getDate();let cells=['L','M','M','G','V','S','D'].map(t=>`<div class="calendar-weekday">${t}</div>`).join('');for(let i=0;i<Math.ceil((first+days)/7)*7;i++){const d=i-first+1,valid=d>0&&d<=days,iso=`${y}-${String(m+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`;const matches=data.filter(a=>a.date===iso);cells+=`<div class="calendar-day ${valid?'':'other'} ${valid&&d===now.getDate()&&m===now.getMonth()&&y===now.getFullYear()?'today':''}">${valid?`<span class="day-num">${d}</span>${matches.slice(0,3).map(a=>`<button class="calendar-event" data-open="appointment" data-id="${esc(a.id)}">${esc(a.time)} ${esc(a.name)}</button>`).join('')}`:''}</div>`}
return heading('Appuntamenti.','Richieste di sopralluogo, consulenze e attività programmate.',canStaff()?'<button class="primary-btn" data-new="appointment">+ Nuovo appuntamento</button>':'')+`<div class="panel"><div class="panel-top"><h2>${new Date(y,m).toLocaleDateString('it-IT',{month:'long',year:'numeric'})}</h2><div class="calendar-controls"><button class="outline-btn btn-small" data-calendar="prev">←</button><button class="outline-btn btn-small" data-calendar="today">Oggi</button><button class="outline-btn btn-small" data-calendar="next">→</button></div></div><div class="panel-body"><div class="calendar-grid">${cells}</div></div></div><div class="panel"><div class="panel-top"><h2>Elenco appuntamenti</h2></div><div class="panel-body table-scroll">${data.length?`<table class="list-table"><thead><tr><th>DATA</th><th>NOMINATIVO</th><th>SERVIZIO</th><th>STATO</th><th></th></tr></thead><tbody>${data.map(a=>`<tr><td><b>${esc(a.date)} ${esc(a.time)}</b></td><td>${esc(a.name)}</td><td>${esc(a.service||'—')}</td><td>${status(a.status)}</td><td><button class="action-icon" data-open="appointment" data-id="${esc(a.id)}">↗</button></td></tr>`).join('')}</tbody></table>`:empty('Nessun appuntamento','Puoi crearne uno o partire da una richiesta.')}</div></div>`}
function renderQuotes(){const data=all('quotes').sort((a,b)=>stamp(b.createdAt)-stamp(a.createdAt));return heading('Preventivi.','Documenti economici da compilare e stampare in PDF.',canStaff()?'<button class="primary-btn" data-new="quote">+ Nuovo preventivo</button>':'')+`<div class="panel"><div class="panel-top"><h2>${data.length} preventivi</h2><span class="text-muted">Esportazione PDF tramite stampa del browser</span></div><div class="panel-body table-scroll">${data.length?`<table class="list-table"><thead><tr><th>RIFERIMENTO</th><th>CLIENTE</th><th>IMPORTO</th><th>STATO</th><th></th></tr></thead><tbody>${data.map(q=>`<tr><td><b>${esc(q.reference||q.id.slice(0,8).toUpperCase())}</b><br><span class="text-muted">${date(q.createdAt)}</span></td><td>${esc(q.clientName)}</td><td><b>${currency(q.total)}</b></td><td>${status(q.status)}</td><td><button class="action-icon" data-open="quote" data-id="${esc(q.id)}">↗</button><button class="action-icon" data-print="${esc(q.id)}" title="Stampa PDF">⇩</button></td></tr>`).join('')}</tbody></table>`:empty('Nessun preventivo','Crea un preventivo, aggiungi le voci e stampa in PDF.')}</div></div><div class="note">La stampa PDF avviene nel browser, senza Cloud Functions. I documenti salvati sul dispositivo non vengono archiviati automaticamente su Firebase Storage.</div>`}
function styledHeadingEditor(key,title,theme='dark'){
 const parts=getStyledHeadingParts(key,state.content),hasAfter=key==='contactHeading';
 return `<section class="cms-heading-editor full" data-heading-editor="${esc(key)}"><div class="cms-heading-editor-header"><strong>${esc(title)}</strong><span>Struttura tipografica · anteprima dal vivo</span></div>
 ${textarea(key+'Primary','Testo principale — colore bianco'+(theme==='light'?' / scuro':''),parts.primary,2)}
 ${textarea(key+'Accent','Testo evidenziato — champagne e corsivo',parts.accent,2)}
 ${hasAfter?textarea(key+'After','Testo conclusivo — stile principale',parts.after,2):''}
 <div class="cms-heading-preview ${theme==='light'?'cms-heading-preview-light':'cms-heading-preview-dark'}"><span class="cms-heading-preview-label">ANTEPRIMA / ${esc(title)}</span><div class="cms-heading-preview-title" data-heading-preview="${esc(key)}"></div></div></section>`;
}
function refreshHeadingPreviews(root=document){
 root.querySelectorAll('[data-heading-editor]').forEach(section=>{
  const key=section.dataset.headingEditor;
  const parts={primary:section.querySelector(`[name="${key}Primary"]`)?.value||'',accent:section.querySelector(`[name="${key}Accent"]`)?.value||'',after:section.querySelector(`[name="${key}After"]`)?.value||''};
  renderStyledHeading(section.querySelector('[data-heading-preview]'),key,parts);
 });
}
function renderContent(){if(!canContent())return heading('Contenuti.','Visualizzazione consentita: modifica riservata a editor e titolare.')+`<div class="note">Il tuo account non dispone dei permessi editoriali.</div>`;const c=state.content;return heading('Contenuti del sito.','Aggiorna i testi pubblici e pubblica direttamente su Firestore.',`<a class="outline-btn" target="_blank" href="../index.html">Visualizza il sito ↗</a>`)+`<div class="panel"><div class="panel-top"><div><h2>Editor contenuti</h2><p>I testi vengono letti dal sito pubblico direttamente dal database.</p></div></div><div class="panel-body"><form id="content-form" class="form-grid">
 ${styledHeadingEditor('heroTitle','Titolo principale / Hero')}
 ${textarea('heroSubtitle','Sottotitolo hero',c.heroSubtitle,3)}${textInput('heroImageUrl','URL fotografia hero (HTTPS, opzionale)',c.heroImageUrl||'')}
 ${textarea('aboutLead','Presentazione breve',c.aboutLead,3)}${textarea('aboutBody','Testo completo studio',c.aboutBody,5)}${textarea('studioHeading','Titolo sezione Studio',c.studioHeading,2)}
 ${styledHeadingEditor('servicesHeading','Titolo / Competenze')}
 ${textarea('servicesIntro','Introduzione Servizi',c.servicesIntro,2)}
 ${styledHeadingEditor('methodHeading','Titolo / Metodo','light')}
 ${styledHeadingEditor('contactHeading','Titolo / Contatti')}
 ${textarea('contactDescription','Introduzione contatti',c.contactDescription,3)}<div class="form-actions"><button type="submit" class="primary-btn">Salva e pubblica ↗</button></div></form></div></div><div class="note">I titoli bicolore mantengono lo stile anche quando cambi le parole. I documenti Firestore precedenti restano compatibili; i testi personalizzati già salvati vengono mostrati nel campo principale, senza eliminazioni automatiche.</div>`}
function renderServices(){const updated=all('services');const data=[...defaultServices.filter(s=>!updated.some(u=>u.id===s.id)),...updated].filter(s=>s.archived!==true).sort((a,b)=>(a.order||0)-(b.order||0));return heading('Servizi.','Aree di competenza presenti sul sito pubblico.',canContent()?'<button class="primary-btn" data-new="service">+ Nuovo servizio</button>':'')+`<div class="panel"><div class="panel-top"><h2>Elenco competenze</h2>${canContent()?'<button class="outline-btn btn-small" data-seed="services">Ripristina 6 servizi predefiniti</button>':''}</div><div class="panel-body table-scroll">${data.length?`<table class="list-table"><thead><tr><th>ORDINE</th><th>SERVIZIO</th><th>DESCRIZIONE</th><th></th></tr></thead><tbody>${data.map(s=>`<tr><td>${esc(s.order)}</td><td><b>${esc(s.icon||'⌖')} ${esc(s.title)}</b></td><td>${esc((s.description||'').slice(0,100))}</td><td><button class="action-icon" data-open="service" data-id="${esc(s.id)}">↗</button></td></tr>`).join('')}</tbody></table>`:empty()}</div></div><div class="note">Se non hai ancora pubblicato documenti in Firestore, il sito usa le sei competenze verificate sul sito attuale. Per modificarle, pubblicale prima nel database.</div>`}
function renderProjects(){const data=all('projects');return heading('Progetti.','Archivio interno: la sezione pubblica Progetti è stata rimossa su richiesta.',canContent()?'<button class="primary-btn" data-new="project">+ Nuovo progetto</button>':'')+`<div class="panel"><div class="panel-body table-scroll">${data.length?`<table class="list-table"><thead><tr><th>TITOLO</th><th>DESCRIZIONE</th><th>STATO</th><th></th></tr></thead><tbody>${data.map(p=>`<tr><td><b>${esc(p.title)}</b></td><td>${esc((p.description||'').slice(0,110))}</td><td>${p.published?'Pronto per pubblicazione':'Bozza'}</td><td><button class="action-icon" data-open="project" data-id="${esc(p.id)}">↗</button></td></tr>`).join('')}</tbody></table>`:empty('Nessun progetto pubblicato','Inserisci fotografie e descrizioni autorizzate dallo studio.')}</div></div><div class="note">Il portfolio pubblico è disattivato. Questi record sono gestiti nel CMS ma non compaiono nel sito. Le immagini sono URL HTTPS esterni; Firebase Storage non è incluso nel piano Spark.</div>`}
function renderSEO(){if(!canContent())return heading('SEO.','Solo lettura per il ruolo attuale.')+`<div class="panel"><div class="panel-body">${esc(state.content.seoTitle)}</div></div>`;return heading('Ottimizzazione SEO.','Metadati pubblici e descrizione per i motori di ricerca.')+`<div class="panel"><div class="panel-top"><h2>Metadati del sito</h2></div><div class="panel-body"><form id="seo-form" class="form-grid">${textInput('seoTitle','Titolo della pagina',state.content.seoTitle,'text','maxlength="160"')}${textarea('seoDescription','Meta description',state.content.seoDescription,3)}${textInput('seoCanonical','URL canonico HTTPS (facoltativo)',state.content.seoCanonical||'','url')}
<div class="form-actions"><button class="primary-btn" type="submit">Salva metadati ↗</button></div></form></div></div><div class="panel"><div class="panel-top"><h2>Pubblicazione SEO statica — Spark gratuito</h2></div><div class="panel-body"><p>Dopo aver salvato i metadati, scarica un <code>index.html</code> con title, description, Open Graph e canonical già aggiornati. Pubblicalo sul tuo hosting per renderli visibili anche ai crawler che non eseguono JavaScript.</p><button type="button" class="outline-btn" data-export="seo-html">Scarica HTML SEO per la pubblicazione ⇩</button><div class="note warning">Questa azione NON modifica automaticamente l'hosting o il dominio. Conserva una copia dell'HTML attuale, quindi sostituisci esclusivamente l'index.html pubblico. Usa il dominio canonico solo quando coincide con quello di pubblicazione.</div></div></div>`}
function renderTeam(){if(!canOwner())return heading('Collaboratori.','Gestione dei ruoli riservata al titolare.')+`<div class="note">Il tuo account non è titolare. Solo il titolare può amministrare gli accessi.</div>`;return heading('Accessi e collaboratori.','Ruoli autorizzati tramite Firebase Authentication e Firestore.','<button class="primary-btn" data-new="member">+ Autorizza UID</button>')+`<div class="panel"><div class="panel-body table-scroll">${all('admins').length?`<table class="list-table"><thead><tr><th>UID FIREBASE AUTH</th><th>RUOLO</th><th>ATTIVO</th><th></th></tr></thead><tbody>${all('admins').map(a=>`<tr><td><b>${esc(a.email||a.id)}</b><br><span class="text-muted">${esc(a.id)}</span></td><td>${esc(roleLabels[a.role]||a.role)}</td><td>${a.active?'Attivo':'Disabilitato'}</td><td><button class="action-icon" data-open="member" data-id="${esc(a.id)}">↗</button></td></tr>`).join('')}</tbody></table>`:empty('Nessun profilo caricato')}</div></div><div class="note warning"><b>Importante:</b> la gestione team associa ruoli a UID già esistenti su Firebase Authentication. Non crea password o utenti Auth. Crea l'utente nel pannello Firebase Authentication, copia il suo UID e poi autorizzalo qui. Non creare UID casuali.</div><div class="permissions-grid">${Object.entries(roleLabels).map(([role,label])=>`<div class="permission-card"><b>${label}</b><span>${{owner:'Gestione completa del CMS e dei ruoli.',editor:'Modifica contenuti, servizi, progetti e SEO.',staff:'Gestione contatti, richieste, appuntamenti e preventivi.',viewer:'Consultazione dei dati senza modifiche.'}[role]}</span></div>`).join('')}</div>`}
