function renderExport(){return heading('Backup e ripristino.','Esporta i dati che puoi leggere. Il ripristino è consentito soltanto al titolare.')+`<div class="panel"><div class="panel-top"><h2>Backup manuale / Firebase Spark</h2></div><div class="panel-body"><p>Esporta richieste, clienti, appuntamenti, preventivi, servizi, archivio progetti e contenuti. Il file JSON rimane sul tuo dispositivo. Conservane copie cifrate in luoghi sicuri.</p><button type="button" class="primary-btn" data-export="json">Esporta archivio JSON ⇩</button><div class="note warning">Il backup manuale non è automatico: organizza una procedura periodica e verifica il file prima di eliminare dati.</div></div></div>${canOwner()?`<div class="panel"><div class="panel-top"><h2>Ripristino controllato — solo Titolare</h2></div><div class="panel-body"><p>Carica un JSON esportato da questo CMS. Il sistema verifica struttura, progetto, ID e numero di record. Il ripristino aggiunge o aggiorna documenti con gli stessi ID, <b>senza cancellare gli altri record</b>. I ruoli amministrativi non vengono mai importati.</p><label>File di backup .json<input type="file" id="backup-restore-file" accept=".json,application/json"></label><div class="note" id="backup-restore-preview" role="status" aria-live="polite">Seleziona un file per visualizzare i dati prima del ripristino.</div><button class="outline-btn" type="button" id="backup-restore-run" disabled>Conferma e ripristina i record ↗</button><p class="text-muted">ATTENZIONE: i documenti con lo stesso ID vengono sovrascritti. Prima di procedere, esporta sempre un backup dello stato corrente. Il processo non è un ripristino atomico dell'intero database.</p></div></div>`:''}`}

function editRequest(id){const r=item('requests',id);if(!r)return;openModal('Richiesta / '+r.fullName,`<div class="note">${esc(r.requestType==='appuntamento'?'Richiesta appuntamento':'Richiesta preventivo')} ricevuta ${date(r.createdAt)}. Il mittente non può leggere o modificare questi dati.</div><div class="form-grid">${textInput('xname','Nome',r.fullName,'text','readonly')}${textInput('xemail','Email',r.email,'email','readonly')}${textInput('xphone','Telefono',r.phone||'','text','readonly')}${textInput('xservice','Servizio',r.service||'','text','readonly')}${r.requestedDate?textInput('xdate','Data richiesta',r.requestedDate,'text','readonly'):''}<label class="full">Messaggio<textarea readonly rows="5">${esc(r.message)}</textarea></label></div>${canStaff()?`<form class="form-grid" data-save="request" data-id="${esc(id)}" style="margin-top:25px">${select('status','Stato pratica',requestStatuses,r.status)}${textInput('assignedTo','Assegnato a',r.assignedTo||'')}${textarea('internalNotes','Note interne (non visibili al cliente)',r.internalNotes||'',4)}<div class="form-actions"><button type="button" class="outline-btn" data-convert="${esc(id)}">Crea scheda cliente</button><button type="button" class="outline-btn" data-from-request="${esc(id)}">Pianifica appuntamento</button><button class="primary-btn" type="submit">Salva richiesta ↗</button></div></form>`:''}`)}
function editClient(id){const c=id?item('clients',id):{};if(id&&!c)return;openModal(id?'Modifica cliente':'Nuovo cliente',`<form class="form-grid" data-save="client" data-id="${esc(id||'')}">${textInput('name','Nome e cognome *',c.name||'','text','required maxlength="120"')}${textInput('company','Azienda / ragione sociale',c.company||'')}${textInput('email','Email',c.email||'','email')}${textInput('phone','Telefono',c.phone||'')}${textInput('address','Indirizzo',c.address||'')}${textarea('notes','Note interne',c.notes||'')}<div class="form-actions">${id?`<button type="button" class="danger-btn" data-delete="clients" data-id="${esc(id)}">Elimina</button>`:''}<button type="button" class="outline-btn" data-dismiss="true">Annulla</button><button class="primary-btn" type="submit">${id?'Salva modifiche':'Crea cliente'} ↗</button></div></form>`)}
function editAppointment(id,pre={}){const a=id?item('appointments',id):pre;if(id&&!a)return;openModal(id?'Modifica appuntamento':'Nuovo appuntamento',`<form class="form-grid" data-save="appointment" data-id="${esc(id||'')}">${textInput('name','Nominativo *',a.name||'','text','required')}${textInput('email','Email',a.email||'','email')}${textInput('phone','Telefono',a.phone||'')}${textInput('service','Servizio',a.service||'')}${textInput('date','Data *',a.date||new Date().toISOString().slice(0,10),'date','required')}${textInput('time','Ora',a.time||'10:00','time')}${select('status','Stato',appointmentStatuses,a.status||'da_confermare')}${textarea('notes','Note interne',a.notes||'')}<div class="form-actions">${id?`<button class="danger-btn" type="button" data-delete="appointments" data-id="${esc(id)}">Elimina</button>`:''}<button class="outline-btn" type="button" data-dismiss="true">Annulla</button><button class="primary-btn" type="submit">Salva appuntamento ↗</button></div></form>`)}
function lineMarkup(x={}){return `<div class="quote-line"><input name="lineLabel" placeholder="Descrizione voce" maxlength="200" value="${esc(x.label||'')}"><input name="lineQty" aria-label="Quantità" title="Quantità" type="number" min="0.01" step="0.01" value="${Number(x.qty||1)}"><input name="linePrice" aria-label="Prezzo" title="Prezzo (€)" type="number" min="0" step="0.01" value="${Number(x.price||0)}"><button class="action-icon" type="button" data-remove-line aria-label="Rimuovi riga">×</button></div>`}
function editQuote(id){const q=id?item('quotes',id):{};if(id&&!q)return;openModal(id?'Modifica preventivo':'Nuovo preventivo',`<form class="form-grid" data-save="quote" data-id="${esc(id||'')}">${textInput('reference','Riferimento',q.reference||('STR-'+new Date().getFullYear()+'-'+String(Date.now()).slice(-5)))}${select('status','Stato',quoteStatuses,q.status||'bozza')}${textInput('clientName','Cliente *',q.clientName||'','text','required')}${textInput('clientEmail','Email cliente',q.clientEmail||'','email')}${textInput('subject','Oggetto',q.subject||'')}${textarea('description','Descrizione generale',q.description||'',3)}<div class="full"><b style="font-size:12px">Voci del preventivo</b><div class="quote-lines" id="quote-lines" style="margin-top:12px">${(q.lines?.length?q.lines:[{label:'',qty:1,price:0}]).map(lineMarkup).join('')}</div><button type="button" class="outline-btn btn-small" data-add-line style="margin-top:12px">+ Aggiungi voce</button><div class="quote-totals" id="quote-total">${currency(q.total||0)}</div><p class="text-muted">Totale delle voci. IVA, ritenute o altri oneri non vengono calcolati automaticamente: specificarli nelle voci, se applicabili.</p></div><div class="form-actions">${id?`<button type="button" class="danger-btn" data-delete="quotes" data-id="${esc(id)}">Elimina</button><button type="button" class="outline-btn" data-print="${esc(id)}">Stampa PDF</button>`:''}<button class="primary-btn" type="submit">Salva preventivo ↗</button></div></form>`);calcQuote()}
function calcQuote(){let total=0;$$('#quote-lines .quote-line').forEach(x=>{const q=Number(x.querySelector('[name=lineQty]').value)||0,p=Number(x.querySelector('[name=linePrice]').value)||0;total+=q*p});if($('#quote-total'))$('#quote-total').textContent=currency(total);return Math.round(total*100)/100}
function editService(id){const defaults=defaultServices.find(s=>s.id===id),s=(id?item('services',id):null)||defaults||{};openModal(id?'Modifica servizio':'Nuovo servizio',`<form class="form-grid" data-save="service" data-id="${esc(id||'')}">${textInput('title','Titolo *',s.title||'','text','required')}${textInput('icon','Simbolo (testo)',s.icon||'⌖')}${textInput('order','Ordine',s.order||7,'number','min="1"')}${textInput('slug','Identificatore (solo nuovi)',id||'','text',id?'readonly':'required pattern="[a-z0-9-]+" placeholder="esempio-servizio"')}${textarea('description','Descrizione',s.description||'')}${textarea('tags','Tag (separati da virgola)',(s.tags||[]).join(', '),2)}<div class="form-actions">${id&&(item('services',id)||defaultServices.some(d=>d.id===id))?`<button type="button" class="danger-btn" data-delete="services" data-id="${esc(id)}">Elimina</button>`:''}<button class="primary-btn" type="submit">Salva servizio ↗</button></div></form>`)}
function editProject(id){const p=id?item('projects',id):{};openModal(id?'Modifica progetto':'Nuovo progetto',`<form class="form-grid" data-save="project" data-id="${esc(id||'')}">${textInput('title','Titolo progetto *',p.title||'','text','required')}${textInput('category','Categoria',p.category||'')}${textInput('imageUrl','URL foto HTTPS',p.imageUrl||'','url')}${textarea('description','Descrizione',p.description||'')}<label class="checkbox-row full"><input type="checkbox" name="published" ${p.published?'checked':''}> Contrassegna come pronto (portfolio pubblico attualmente disattivato)</label><div class="form-actions">${id?`<button type="button" class="danger-btn" data-delete="projects" data-id="${esc(id)}">Elimina</button>`:''}<button class="primary-btn" type="submit">Salva progetto ↗</button></div></form>`)}
function editMember(id){if(!canOwner())return;const m=id?item('admins',id):{};openModal(id?'Modifica collaboratore':'Autorizza nuovo collaboratore',`<div class="note">L'utente deve essere già stato creato in Firebase Authentication. Inserisci il suo UID esatto, non l'indirizzo email.</div><form class="form-grid" data-save="member" data-id="${esc(id||'')}">${textInput('uid','UID Firebase Authentication *',id||'','text',id?'readonly':'required minlength="20"')}${textInput('email','Email di riferimento',m.email||'','email')}${select('role','Ruolo',Object.entries(roleLabels),m.role||'staff')}<label class="checkbox-row"><input type="checkbox" name="active" ${id?m.active?'checked':'':'checked'}> Account attivo</label><div class="form-actions">${id&&id!==state.user.uid?`<button type="button" class="danger-btn" data-delete="admins" data-id="${esc(id)}">Rimuovi ruolo</button>`:''}<button class="primary-btn" type="submit">Salva autorizzazione ↗</button></div></form>`)}

function printQuote(id){const q=item('quotes',id);if(!q)return;const lines=q.lines||[],total=lines.reduce((sum,l)=>sum+Number(l.qty||0)*Number(l.price||0),0);
 const studio=state.content;const printAddress=esc(studio.address||defaultContent.address),printPhone=esc(studio.phone||defaultContent.phone),printEmail=esc(studio.email||defaultContent.email);
 const printVat=esc(studio.vatNumber||defaultContent.vatNumber);
 const printDemo=(studio.vatNumber||defaultContent.vatNumber)==='00000000000';
 const html=`<!doctype html><html lang="it"><head><meta charset="utf-8"><title>${esc(q.reference)} - Studio Russu</title><style>body{font-family:Arial,sans-serif;color:#172c32;padding:55px;max-width:830px;margin:auto}header{display:flex;justify-content:space-between;align-items:start;padding-bottom:35px;border-bottom:3px solid #1c343c}.brand{font-size:30px;font-weight:bold}.meta{color:#758689;font-size:12px;line-height:1.7}h1{margin:45px 0 15px;font-size:35px}table{width:100%;border-collapse:collapse;margin:30px 0}th{text-align:left;background:#edf0ed;font-size:11px;padding:13px}td{border-bottom:1px solid #e1e6e1;padding:15px 13px;font-size:12px}.total{text-align:right;font-size:24px;font-weight:bold}.footer{margin-top:85px;border-top:1px solid #ddd;padding-top:20px;color:#7e8e8a;font-size:11px}@media print{body{padding:22px}.no-print{display:none}}</style></head><body><header><div class="brand">STUDIO TECNICO<br>RUSSU.</div><div class="meta">${printAddress}<br>${printPhone} · ${printEmail}<br>P.IVA ${printVat}${printDemo?" · DATO DIMOSTRATIVO / NON VALIDO":""}</div></header><h1>Preventivo ${esc(q.reference||'')}</h1><p><b>Cliente:</b> ${esc(q.clientName)}<br><b>Email:</b> ${esc(q.clientEmail||'—')}<br><b>Oggetto:</b> ${esc(q.subject||'—')}</p><p>${esc(q.description||'')}</p><table><thead><tr><th>DESCRIZIONE</th><th>Q.TÀ</th><th>UNITARIO</th><th>IMPORTO</th></tr></thead><tbody>${lines.map(l=>`<tr><td>${esc(l.label)}</td><td>${esc(l.qty)}</td><td>${currency(l.price)}</td><td>${currency(Number(l.qty)*Number(l.price))}</td></tr>`).join('')}</tbody></table><div class="total">Totale voci: ${currency(total)}</div><p class="meta">Eventuali IVA, contributi, ritenute o altri oneri sono inclusi solo se esplicitamente indicati nelle voci. Documento da verificare prima dell'invio al cliente.</p><div class="footer">Documento generato dal CMS Studio Tecnico Russu · ${new Date().toLocaleDateString('it-IT')}</div><button class="no-print" onclick="window.print()">Stampa / Salva come PDF</button></body></html>`;
 const w=window.open('','_blank');if(!w){toast('Consenti i popup del browser per esportare il PDF.',true);return}w.document.open();w.document.write(html);w.document.close();w.focus()}

async function saveForm(form){const kind=form.dataset.save,id=form.dataset.id||'',fd=new FormData(form);const get=k=>String(fd.get(k)||'').trim();let collectionName='',data={},documentId=id;
 if(kind==='request'){if(!requireRole('staff'))return;collectionName='requests';data={status:get('status'),assignedTo:get('assignedTo'),internalNotes:get('internalNotes'),updatedAt:serverTimestamp()}}
 else if(kind==='client'){if(!requireRole('staff'))return;collectionName='clients';data={name:get('name'),company:get('company'),email:get('email'),phone:get('phone'),address:get('address'),notes:get('notes'),updatedAt:serverTimestamp()};if(!data.name)throw Error('Inserisci il nome cliente.')}
 else if(kind==='appointment'){if(!requireRole('staff'))return;collectionName='appointments';data={name:get('name'),email:get('email'),phone:get('phone'),service:get('service'),date:get('date'),time:get('time'),status:get('status'),notes:get('notes'),updatedAt:serverTimestamp()};if(!data.name||!data.date)throw Error('Nome e data sono obbligatori.')}
 else if(kind==='quote'){if(!requireRole('staff'))return;collectionName='quotes';const rows=[...form.querySelectorAll('.quote-line')];const lines=rows.map(r=>({label:r.querySelector('[name=lineLabel]').value.trim(),qty:Number(r.querySelector('[name=lineQty]').value),price:Number(r.querySelector('[name=linePrice]').value)})).filter(l=>l.label&&l.qty>0&&l.price>=0);if(!lines.length||lines.some(l=>!Number.isFinite(l.qty)||!Number.isFinite(l.price)||l.qty>1e6||l.price>1e9))throw Error('Controlla le voci: quantità e prezzi devono essere numeri finiti e validi.');data={reference:get('reference'),status:get('status'),clientName:get('clientName'),clientEmail:get('clientEmail'),subject:get('subject'),description:get('description'),lines,total:Math.round(lines.reduce((s,l)=>s+l.qty*l.price,0)*100)/100,updatedAt:serverTimestamp()};if(!data.clientName)throw Error('Il nominativo del cliente è obbligatorio.')}
 else if(kind==='service'){if(!requireRole('content'))return;collectionName='services';documentId=id||get('slug');if(!/^[a-z0-9-]+$/.test(documentId))throw Error('Usa uno slug con sole lettere minuscole, numeri e trattini.');data={title:get('title'),icon:get('icon'),order:Number(get('order'))||99,description:get('description'),tags:get('tags').split(',').map(x=>x.trim()).filter(Boolean),archived:false,updatedAt:serverTimestamp()};if(!data.title)throw Error('Il titolo è obbligatorio.')}
 else if(kind==='project'){if(!requireRole('content'))return;collectionName='projects';data={title:get('title'),category:get('category'),imageUrl:get('imageUrl'),description:get('description'),published:fd.has('published'),updatedAt:serverTimestamp()};if(data.imageUrl&&!/^https:\/\//i.test(data.imageUrl))throw Error('Inserisci un URL immagine HTTPS.');if(!data.title)throw Error('Il titolo è obbligatorio.')}
 else if(kind==='member'){if(!requireRole('owner'))return;collectionName='admins';documentId=id||get('uid');if(documentId.length<20)throw Error('UID Firebase non valido.');if(documentId===state.user.uid&&(!fd.has('active')||get('role')!=='owner'))throw Error('Non puoi disattivare o declassare il tuo account titolare.');data={email:get('email'),role:get('role'),active:fd.has('active'),updatedAt:serverTimestamp()}}
 else return;
 if(!documentId)data.createdAt=serverTimestamp();
 if(documentId){if(kind==='service'||kind==='member')await setDoc(doc(db,collectionName,documentId),data,{merge:true});else await updateDoc(doc(db,collectionName,documentId),data)}else await addDoc(collection(db,collectionName),data);
 if(kind==='member'){const s=await getDocs(collection(db,'admins'));state.collections.admins=s.docs.map(d=>({id:d.id,...d.data()}))}else await refresh(collectionName);
 closeModal();toast('Dati salvati correttamente.');render();
}
async function saveContent(form){if(!requireRole('content'))return;const data={},fd=new FormData(form);for(const [k,v] of fd.entries())data[k]=String(v).trim();
 if(form.id==='settings-form' && data.vatNumber && !/^\d{11}$/.test(data.vatNumber))throw Error('La Partita IVA deve contenere esattamente 11 cifre.');
 if(form.id==='seo-form' && data.seoCanonical && !/^https:\/\/[^\s#]+$/i.test(data.seoCanonical))throw Error('Inserisci un indirizzo canonico HTTPS valido.');if(data.heroImageUrl&&!/^https:\/\//i.test(data.heroImageUrl))throw Error('La fotografia della hero deve utilizzare un URL HTTPS.');
 // Keep legacy single-string fields in sync for older clients and exported backups.
 if(form.id==='content-form')for(const key of Object.keys(styledHeadingConfig)){
  const pieces=[data[key+'Primary'],data[key+'Accent'],data[key+'After']].filter(x=>typeof x==='string'&&x.trim());
  if(!pieces.length)throw Error('Inserisci almeno una parte del titolo: '+key);
  data[key]=pieces.join(' ').replace(/\s+/g,' ').trim();
 }
 await setDoc(doc(db,'siteContent','main'),{...data,updatedAt:serverTimestamp()},{merge:true});Object.assign(state.content,data);toast('Modifiche pubblicate nel database.');render()}
async function convertRequest(id){if(!requireRole('staff'))return;const r=item('requests',id);if(!r)return;const found=all('clients').find(c=>c.email&&c.email.toLowerCase()===String(r.email||'').toLowerCase());if(found){toast('Cliente già presente nel CRM.');editClient(found.id);return}await addDoc(collection(db,'clients'),{name:r.fullName,email:r.email,phone:r.phone||'',company:'',address:'',notes:`Da richiesta ${r.requestType}: ${r.service}`,createdAt:serverTimestamp(),updatedAt:serverTimestamp()});await refresh('clients');toast('Cliente aggiunto al CRM.');closeModal()}
async function seedServices(){if(!requireRole('content'))return;if(!confirm('Ripristinare i sei servizi predefiniti? Eventuali modifiche ai sei servizi di base saranno sovrascritte.'))return;for(const service of defaultServices){const {id,...data}=service;await setDoc(doc(db,'services',id),{...data,archived:false,updatedAt:serverTimestamp()},{merge:true})}await refresh('services');toast('Servizi pubblicati.')}
async function exportJSON(){const data={exportedAt:new Date().toISOString(),firebaseProject:'studio-russu',collections:{},siteContent:state.content};for(const k of ['requests','clients','appointments','quotes','services','projects'])data.collections[k]=all(k).map(v=>JSON.parse(JSON.stringify(v,(key,value)=>value?.toDate?value.toDate().toISOString():value)));if(canOwner())data.collections.admins=all('admins');const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`studio-russu-backup-${new Date().toISOString().slice(0,10)}.json`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Backup JSON esportato: custodiscilo in modo sicuro.')}


// Spark: exporta HTML statico per SEO senza backend o Cloud Functions.
async function downloadSEOHTML(){
 if(!requireRole('content'))return;
 const response=await fetch('../index.html',{cache:'no-store'});
 if(!response.ok)throw Error('Impossibile recuperare index.html dal sito pubblicato.');
 const source=await response.text(),page=new DOMParser().parseFromString(source,'text/html');
 const title=String(state.content.seoTitle||defaultContent.seoTitle).slice(0,160);
 const description=String(state.content.seoDescription||defaultContent.seoDescription).slice(0,300);
 page.title=title;
 function setMeta(attr,key,value){let meta=[...page.head.querySelectorAll('meta')].find(m=>m.getAttribute(attr)===key);if(!meta){meta=page.createElement('meta');meta.setAttribute(attr,key);page.head.append(meta)}meta.setAttribute('content',value)}
 setMeta('name','description',description);
 setMeta('property','og:title',title);setMeta('property','og:description',description);
 setMeta('name','twitter:title',title);setMeta('name','twitter:description',description);
 const canonical=String(state.content.seoCanonical||'').trim();
 if(canonical){const parsed=new URL(canonical);if(parsed.protocol!=='https:')throw Error('URL canonico non HTTPS.');let link=page.querySelector('link[rel="canonical"]');if(!link){link=page.createElement('link');link.rel='canonical';page.head.append(link)}link.href=parsed.href}
 const html='<!doctype html>\n'+page.documentElement.outerHTML;
 const blob=new Blob([html],{type:'text/html;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');
 a.href=url;a.download='index-seo-da-pubblicare.html';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1200);
 toast('HTML SEO generato. Rinomina in index.html e pubblica il file dopo il controllo.');
}

// Ripristino manuale non distruttivo (upsert) con anteprima; non tocca mai gli account admins.
const RESTORE_COLLECTIONS=['requests','clients','appointments','quotes','services','projects'];
let checkedRestore=null;
function restoreTimestamp(value){
 if(typeof value==='string'&&/^\d{4}-\d{2}-\d{2}T/.test(value)){const d=new Date(value);if(Number.isFinite(d.getTime()))return Timestamp.fromDate(d)}
 if(value&&typeof value==='object'&&Number.isSafeInteger(value.seconds)&&Number.isInteger(value.nanoseconds))return new Timestamp(value.seconds,value.nanoseconds);
 return value;
}
function sanitizedBackupDocument(input){
 if(!input||typeof input!=='object'||Array.isArray(input))throw Error('Record del backup non valido.');
 const id=input.id;
 if(typeof id!=='string'||!/^[A-Za-z0-9_-]{1,160}$/.test(id))throw Error('ID documento non valido nel backup.');
 const result={};
 for(const [field,value] of Object.entries(input)){
  if(field==='id')continue;
  if(!/^[a-zA-Z][a-zA-Z0-9_]{0,80}$/.test(field))throw Error('Campo del backup non consentito.');
  result[field]=(field==='createdAt'||field==='updatedAt')?restoreTimestamp(value):value;
 }
 if(JSON.stringify(result).length>800000)throw Error('Un documento supera le dimensioni consentite.');
 return {id,data:result};
}
async function inspectBackup(file){
 checkedRestore=null;const preview=$('#backup-restore-preview'),run=$('#backup-restore-run');
 if(run)run.disabled=true;
 if(!preview)return;
 if(!file){preview.textContent='Nessun file selezionato.';return}
 try{
  if(file.size>10*1024*1024)throw Error('File troppo grande (massimo 10 MB per un ripristino guidato).');
  const backup=JSON.parse(await file.text());
  if(!backup||backup.firebaseProject!==firebaseConfig.projectId||!backup.collections||typeof backup.collections!=='object')throw Error('Questo file non appartiene al progetto Firebase studio-russu oppure non è un backup valido.');
  const entries={};let total=0;
  for(const key of RESTORE_COLLECTIONS){const list=backup.collections[key];if(!Array.isArray(list))throw Error('La collezione '+key+' manca o è malformata.');const seen=new Set();entries[key]=list.map(raw=>{
   const value=sanitizedBackupDocument(raw);if(seen.has(value.id))throw Error('ID duplicato in '+key);seen.add(value.id);return value;
  });total+=entries[key].length}
  if(total>5000)throw Error('Ripristino di oltre 5000 record: dividere il backup in lotti verificati.');
  const content={};for(const key of Object.keys(defaultContent))if(typeof backup.siteContent?.[key]==='string')content[key]=backup.siteContent[key];
  for(const name of Object.keys(styledHeadingConfig))for(const suffix of ['Primary','Accent','After']){
   const key=name+suffix;if(typeof backup.siteContent?.[key]==='string')content[key]=backup.siteContent[key];
  }
  checkedRestore={entries,content,total,fileName:file.name};
  preview.textContent=`Backup valido (${file.name}). Record da aggiungere/aggiornare: ${total}; campi contenuti: ${Object.keys(content).length}. Le autorizzazioni admins non verranno importate. Non vengono cancellati altri record.`;
  if(run)run.disabled=false;
 }catch(error){preview.textContent='Backup non valido: '+error.message;checkedRestore=null}
}
async function restoreBackup(){
 if(!requireRole('owner')||!checkedRestore)throw Error('Seleziona prima un backup valido.');
 const choice=prompt(`Stai per importare ${checkedRestore.total} record in ${firebaseConfig.projectId}. I record esistenti con lo stesso ID saranno aggiornati. Digita RIPRISTINA per confermare.`);
 if(choice!=='RIPRISTINA')return;
 const button=$('#backup-restore-run');if(button)button.disabled=true;
 let written=0;
 try{
  const writes=[];for(const key of RESTORE_COLLECTIONS)for(const record of checkedRestore.entries[key])writes.push({ref:doc(db,key,record.id),value:record.data});
  if(Object.keys(checkedRestore.content).length)writes.push({ref:doc(db,'siteContent','main'),value:checkedRestore.content});
  // Limite conservativo per batch Firestore. In caso di errore, batch precedenti potrebbero già essere stati committati.
  for(let i=0;i<writes.length;i+=200){const batch=writeBatch(db);for(const entry of writes.slice(i,i+200))batch.set(entry.ref,entry.value,{merge:true});await batch.commit();written+=Math.min(200,writes.length-i)}
  await loadAll();render();toast('Ripristino completato: '+written+' documenti aggiunti o aggiornati.');checkedRestore=null;
 }catch(error){fail(Error(`Ripristino parziale o non riuscito (${written} documenti confermati). Controlla il database e riprova solo dopo verifica: ${error.message}`));}
 finally{if(button?.isConnected)button.disabled=false}
}
document.addEventListener('change',e=>{if(e.target?.id==='backup-restore-file')inspectBackup(e.target.files?.[0])});
document.addEventListener('click',e=>{if(e.target.closest('#backup-restore-run'))restoreBackup()});

// One click router is used by desktop and mobile layouts. Never trust it for authorization:
// every write also checks the role in Firestore Security Rules.
document.addEventListener('click',async e=>{
 const target=e.target.closest('[data-goto],[data-new],[data-open],[data-refresh],[data-calendar],[data-dismiss],[data-delete],[data-convert],[data-from-request],[data-add-line],[data-remove-line],[data-print],[data-seed],[data-export],[data-notifications]');if(!target)return;
 try{
  if(target.dataset.goto)return show(target.dataset.goto);
  if(target.dataset.dismiss)return closeModal();
  if(target.dataset.new){const k=target.dataset.new;({client:()=>editClient(''),appointment:()=>editAppointment(''),quote:()=>editQuote(''),service:()=>editService(''),project:()=>editProject(''),member:()=>editMember('')})[k]?.();return}
  if(target.dataset.open){const k=target.dataset.open,id=target.dataset.id;({request:()=>editRequest(id),client:()=>editClient(id),appointment:()=>editAppointment(id),quote:()=>editQuote(id),service:()=>editService(id),project:()=>editProject(id),member:()=>editMember(id)})[k]?.();return}
  if(target.dataset.refresh){await refresh(target.dataset.refresh);toast('Dati aggiornati.');return}
  if(target.dataset.calendar){if(target.dataset.calendar==='today'){state.calendarMonth=new Date().getMonth();state.calendarYear=new Date().getFullYear()}else{const d=new Date(state.calendarYear,state.calendarMonth+(target.dataset.calendar==='next'?1:-1),1);state.calendarMonth=d.getMonth();state.calendarYear=d.getFullYear()}render();return}
  if(target.hasAttribute('data-add-line')){$('#quote-lines')?.insertAdjacentHTML('beforeend',lineMarkup());calcQuote();return}
  if(target.hasAttribute('data-remove-line')){target.closest('.quote-line')?.remove();calcQuote();return}
  if(target.dataset.print){printQuote(target.dataset.print);return}
  if(target.dataset.convert){await convertRequest(target.dataset.convert);return}
  if(target.dataset.fromRequest){const r=item('requests',target.dataset.fromRequest);if(r)editAppointment('',{name:r.fullName,email:r.email,phone:r.phone,service:r.service,date:r.requestedDate||''});return}
  if(target.dataset.seed==='services'){await seedServices();return}
  if(target.dataset.export==='json'){await exportJSON();return}
  if(target.dataset.export==='seo-html'){await downloadSEOHTML();return}
  if(target.dataset.notifications==='enable'){if(!('Notification' in window))return toast('Browser non compatibile con le notifiche.',true);if(!window.isSecureContext)return toast('Le notifiche richiedono HTTPS.',true);const permission=await Notification.requestPermission();toast(permission==='granted'?'Notifiche browser abilitate.':'Notifiche non autorizzate.',permission!=='granted');return}
  if(target.dataset.delete){const k=target.dataset.delete,id=target.dataset.id;if(!((['services','projects'].includes(k)&&canContent())||(['requests','appointments','clients','quotes'].includes(k)&&canStaff())||(k==='admins'&&canOwner())))return toast('Operazione non autorizzata.',true);if(k==='admins'&&id===state.user.uid)return toast('Non puoi eliminare il tuo profilo titolare.',true);if(!confirm('Eliminare definitivamente questo record? Questa operazione non è reversibile.'))return;if(k==='services'&&defaultServices.some(s=>s.id===id))await setDoc(doc(db,'services',id),{archived:true,updatedAt:serverTimestamp()},{merge:true});
  else await deleteDoc(doc(db,k,id));if(k==='admins'){const s=await getDocs(collection(db,'admins'));state.collections.admins=s.docs.map(d=>({id:d.id,...d.data()}))}else await refresh(k);closeModal();toast('Record eliminato.');return}
 }catch(error){fail(error)}
});
